mapper.select:

where c.del_flag = '0'

    AND c.patient_id = #{patientId}


    AND c.doctor_id = #{doctorId}


    AND c.status = #{status}


    AND c.title like concat('%', #{title}, '%')


    AND c.room_name = #{roomName}


    AND (c.patient_id = #{params.participantUserId} OR c.doctor_id = #{params.participantUserId})

order by c.create_time desc

