update t_consultation
doctor_id = #{doctorId}, room_name = #{roomName}, status = #{status}, title = #{title}, description = #{description}, start_time = #{startTime}, end_time = #{endTime}, update_by = #{updateBy}, update_time = #{updateTime}, remark = #{remark},
where consultation_id = #{consultationId}
